files.content:
.ds {
  --ds-token-typography-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-token-typography-font:var(--p-font,Pretendard, sans-serif);
  --ds-token-typography-text-sm:var(--p-text-sm,13px);
  --ds-token-typography-text-md:var(--p-text-md,16px);
  --ds-token-typography-text-lg:var(--p-text-lg,24px);
}
.ds .ds-token-typography { display:grid; gap:8px; justify-items:start; }
.ds .ds-token-type { font:600 38px var(--ds-token-typography-display-font); letter-spacing:-.05em; }
.ds .ds-token-sizes { display:flex; align-items:baseline; gap:16px; font-family:var(--ds-token-typography-font); }
.ds .ds-token-sizes [data-token="sm"] { font-size:var(--ds-token-typography-text-sm); }
.ds .ds-token-sizes [data-token="md"] { font-size:var(--ds-token-typography-text-md); }
.ds .ds-token-sizes [data-token="lg"] { font-size:var(--ds-token-typography-text-lg); }
